WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (388::BIGINT, 'No lo sentí tan mal cómo lo pintan, sí que le falta mucho en el tema de la actitud que tiene pero aún así siento que sí se puede disfrutar del curso y aprender bastante. Eso sí, tómese las clases con seriedad y preste mucha atención. Si hace los ejercicios que recomienda a tiempo le va bien'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-07-21T00:00:00+00:00'::TIMESTAMPTZ, '8317afc3fc1ce97762250838f2abc5a77dadb483fbe9f13a93c08fc05491bb0e'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Es una buena opción si usted quiere pasar bien y aprender. Los laboratorios son muy sencillos y el profe califica suave, solo en los quices si califica un poco más rudo. Da materiales de apoyo y explica bien a alguna duda que usted tenga.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria']::TEXT[], '2026-07-20T00:00:00+00:00'::TIMESTAMPTZ, '56d8648653d8f49f63bd35fa6380d89bba207f9c801044484b3a5a531d1685b6'::TEXT, ARRAY[1261]::BIGINT[]),
    (388::BIGINT, 'Entre él y William, sin duda es la mejor opción. El lab es fácil con él y sí se aprende bien. Califica algo duro los informes pero da buena retroalimentación, además de que si da bastante material para que uno realmente pueda hacerlos bien. Meta sin miedo, si le pone pasa fácil y con buena nota.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2026-07-02T00:00:00+00:00'::TIMESTAMPTZ, '196c67dfb748c51a2cab754247dde6fc33a68bcdf49c45ea20d9cea25a73efe2'::TEXT, ARRAY[1261]::BIGINT[]),
    (388::BIGINT, 'No parece que le importe mucho nada más que el curso, sus clases son aburridas y se toma muy enserio el curso aunque sea de relleno, no es malo pero tampoco lo recomendaría mucho, quita completamente las ganas de estar ahí.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-25T00:00:00+00:00'::TIMESTAMPTZ, 'b6010a46164a0e3c3508c4791c1e26b8d28c5d8daf7ddc205f7954b0eb42bea2'::TEXT, ARRAY[1255]::BIGINT[]),
    (388::BIGINT, 'La vdd mejor busque otro profe para lab, preguntarle algo es un caso porque no le gusta aclarar dudas y responde super chocante, al ser el de los primeros cursos debería de motivar al estudiante pero más bien indispone y es mejor ahorrarse aguantar esa actitud, los quices son fáciles y califica suav'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-16T00:00:00+00:00'::TIMESTAMPTZ, '9b940d238776f05c0c018387d3351409cde2ec99a0dc9e4c2ba01041952422ba'::TEXT, ARRAY[1256]::BIGINT[]),
    (388::BIGINT, 'Si es la primera vez llevando CC, mejor busque a otro profesor. Explica relativamente bien, pero se enreda mucho, por lo que quedan dudas. Califica justo y las tareas son fáciles. Los exámenes no son muy complicados y pone fórmulas. Solo responde dudas en clase y solo de la materia de ese día.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '096e7bb4361db463f8f62a44f04447dd2d5694023cc6dc4e88dfab3b415a4b48'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Es de las mejores opciones para CC, las tareas son sencillas, los examenes son un poco difíciles a veces pero deja ejercicios de pts extra y califica algo suave a veces, al preguntarle algo responde de una manera chocante o se desvía del tema y la duda siempre queda'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '7c848b73b3377e28709d78cc233f6f0cee6baa0e3929a134781cef7c9e3fadb7'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Lastima, porque para por lo menos este curso usted quiere llegar a aprender bastante y se nota que el mae no le interesa nada y tampoco ayuda en nada. No es mala nota ni nada pero tiene una actitud muy ahuevada.'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '0619d17c08705ee42989fb276224e3be02592c42d1fa816538e5c96831b24a44'::TEXT, ARRAY[1255]::BIGINT[]),
    (388::BIGINT, 'Siento que de todos los profesores para CC es como el que está mejor, los exámenes no son fáciles pero tampoco imposibles, da puntos extra en los exámenes, el único contra es que su manera de hablar es un poco monótona y da un poco de sueño, pero dejando eso de lado es un buen profesor, califica bie'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2025-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'b33df41af6237cef0e082aa7a6db5df57364b353d86d459e70ad93f9db7a83dc'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'CC es un curso bonito, con él como profe me parece que se aprende mucho pero es verdad lo que dicen de que las clases son super aburridas, ChatGPT tiene más carisma que el. Los exámenes son NORMALES no son fáciles, pone ejercicios extra. Las tareas son EZ, es buena persona pero como quetieneautismo'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2025-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'f070a308355967041b02f36a1fdb864b3d2337bc70d01c89d9274a6a4b1ebbbb'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'El profe es lo peor, es malísimo, nunca está dispuesto a ayudar en nada. En CC podrá ser regular pero en laboratorio es el peor profesor que existe. Si usted le pide ayuda, le responde de malísima gana, no meta con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2025-11-10T00:00:00+00:00'::TIMESTAMPTZ, 'a4e5704673068caf0a31caaa678315c132a82c03124c00b058b21f45be25c776'::TEXT, ARRAY[1261]::BIGINT[]),
    (388::BIGINT, 'no aprendí nada en lab con él, muy mal profesor, no lo recomendaría para ningún curso.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2025-09-27T00:00:00+00:00'::TIMESTAMPTZ, 'ac204cf856b5668392ffdd71b3ce531d809a5de1fed110b884497fa195b7e777'::TEXT, ARRAY[1261]::BIGINT[]),
    (388::BIGINT, 'El profesor como tal no es malo y el laboratorio se pasa muy fácil, pero se nota que tiene problemas de actitud, es muy amargado y parece que ni quiere dar clases. Las clases de cc y lab con el no son nada del otro mundo pero tampoco es un profesor amigable con sus estudiantes.'::TEXT, 10.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2025-08-11T00:00:00+00:00'::TIMESTAMPTZ, 'd9d3c294030b52d491008c16da17f8edd2fc89f8b36012199aa3dddaebaa37cd'::TEXT, ARRAY[1261]::BIGINT[]),
    (388::BIGINT, 'Un profesor tranquilo, 4 exámenes y una tarea por cada examen, explica la materia de manera completa, eso si no deje que se acumule porque si no, no lo logra.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-28T00:00:00+00:00'::TIMESTAMPTZ, 'f2a0bb53fbd469d4899340a6f764b457939d4302a257fb781ffaf5e98b3eb7f2'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Es un buen profe, explica la materia de manera adecuada y hace varios ejemplos en clases. Los exámenes tiene una dificultad normal y la tareas tambien. Puede ir retrasado con respecto a otros profes en la materia, pero siempre cubre todos los temas, y no se siente que de la materia muy rápido.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-20T00:00:00+00:00'::TIMESTAMPTZ, '0515055bece641b46f15f0a81ee1e0b4030bc661c3809d6c35ad812c48ac94cc'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Consta de 2 examenes (bastante faciles), 11 experimentos y 3 infomes. El segundo informe fue corregir el primer informe. Para la bitacora se demora como 10-20 minutos en completar. Se pasa bien con ese profe y es muy al grano con los experimentos. Los informes son en Latex.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Pocos exámenes']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, '025b6ad2225be7b574f8936dca59e2e5e7a19eb53dc4dbde888b98e974a0b3a0'::TEXT, ARRAY[1256]::BIGINT[]),
    (388::BIGINT, '4 exámenes, 4 tareas. El profesor explica súper bien, la verdad para mí la mejor opción para matricular cc. No se siente al fondo de la clase (tampoco habla taaan alto), ni use el cel. 100% recomendado, los exámenes son fáciles y las tareas también.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-01T00:00:00+00:00'::TIMESTAMPTZ, 'e88abca85b17e673788dfe2658f096d179381da5108fe92502cc379cbdc8bc4d'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Explica bien. A veces la clase puede hacerse aburrida por su tono de voz monótono, pero explica toda la materia y hace ejercicios útiles. Responde sin problema a consultas y hace los exámenes con una dificultad bastante normal, métale sin miedo pero si puede aproveche meter tutoría'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'bd38bafb12e9b143336d97d8c60e44f53dd79b4d7685b08dc05f1c5abd154aaa'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'El curso con el es fácil y no se siente tan pesado, solo son 3 informes, y los examenes son bastante fáciles, diría que lo mas dificil son los quices ya que califica duro pero realmente no valen tanto asi que no hay mucho problema.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2025-06-23T00:00:00+00:00'::TIMESTAMPTZ, '03db4ce5e742f5dc5453c9979464c782aa07d4adb36a46786454445272d66743'::TEXT, ARRAY[1256]::BIGINT[]),
    (388::BIGINT, 'El curso se pasa regalado, el profe solo califica seriamente los informes que suelen ser solo 3 por lo que no castiga tanto. No es un profe que sea muy amable cuando se le solicita ayuda, al menos dentro del lab no lo es, pero de igual forma se pasa muy fácil.'::TEXT, 10.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clase fácil', 'Asistencia obligatoria']::TEXT[], '2024-11-30T00:00:00+00:00'::TIMESTAMPTZ, '95b2cbf202a9da58474bceb906cb7ea36dfb76bd8a21b7ac5fe3506fc6ad03c2'::TEXT, ARRAY[1261]::BIGINT[]),
    (388::BIGINT, 'La verdad no sé por qué se quejan de él, es buen profe, siempre pasa preguntando si hay dudas. Creo que exageran con lo de que habla hablo, él habla normal. Él toma los ejercicios de los exámenes del libro, s i quiere aprender y pasar, llévelo con él, no se van a arrepentir.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2024-11-29T00:00:00+00:00'::TIMESTAMPTZ, '865c167168f3ba8f57c6ef17a7d84e62a147fed118fd5e8cb2fe20093067a167'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'El profe explica muy bien. Es conciso en la teoría y hace muchos ejemplos en clase paso por paso. Lo malo es que las clases son MUY aburridas y el profe no se esfuerza en hacerlas más entretenidas, por lo que es fácil perderse. Pero si le logra ponerle atención los temas quedan bastantes claros'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-24T00:00:00+00:00'::TIMESTAMPTZ, '26494d16dd0b790595ceb7db9c167a9d068e4c5ea20002e0790dfe2c6366ae52'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Él literalmente no enseña, usted se las tiene que ingeniar para ver qué hacer y si le pregunta algo responde de una manera demasiado vaga, nunca da claridad con la distribución de puntos en evaluaciones y califica rudo, las clases son muy aburridas y es muy exigente, nunca se le queda bien.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'f0a0e752023028d3656bba2b8d8a17fdb7d1819e303b3926c25071bd1be9492a'::TEXT, ARRAY[1256]::BIGINT[]),
    (388::BIGINT, 'Todos los profes de CC son malos. Pero este es menos malo. Sin embargo, no ayuda con dudas, en clases habla muy bajo, sus clases son ABURRIDAS y su tono es monótono, y cuesta mucho que acepte reclamos. No es muy amigable. Sus evaluaciones son fáciles, en exámenes hay puntos extra.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '168ce313afe8dee971383d7205e10d0d94e6dda7e23d43ad4dffcfca538c855b'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Las clases son muy aburridas, pero en realidad el profe es buena persona y tiene mucha paciencia con las dudas. Matriculen sin miedo(con más razón considerando las alternativas para cc) eso sí, procure sentarse lo más adelante que pueda, ya que el profe habla muy bajo'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-18T00:00:00+00:00'::TIMESTAMPTZ, '32e5d4bf15225c54ffc27c0a9013a1a5c56c6a19ea71008f66e837978933164b'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'como profe es malo, como persona es amargado, los temas del primer examen si los explico, después decidió que no quería ser profe y comenzó con los PowerPoint, los últimos exámenes no vale la pena ir a clase lean del libro, vean mate fácil y la teacher, legalmente no contesta dudas le da pereza,etc.'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-16T00:00:00+00:00'::TIMESTAMPTZ, '919fb1f16c3956bd795425e3e407cb1d7aca6b802b3a760f48d45e364bab06e9'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'CC es un curso pesado, pero me ayudó que el profesor hiciera muchos ejercicios en clase. Las tareas son sencillas.Las clases sí se hacen aburridas por el poco entusiasmo del profesor. Es mejor que estudie bastante los ejercicios del libro.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0d57722dd541e1dd357ffe757d2ef6e92d1908e6e62ccf0ce7b5d58b1758105f'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'La clase es demasiado aburrida por lo que uno se pierde fácilmente, hay que ser autodidacta, no deja evaluaciones por lo que uno no está seguro de cómo evalúa, la distribución de puntaje en los exámenes es muy mala'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2023-06-20T00:00:00+00:00'::TIMESTAMPTZ, '20809fb66f2c66555b000871b2605c6eb8e0592a1bca5749a1353dcacf36b690'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Sus clases son exageradamente aburridas y monótonas. No explica mal, pero el poco entusiasmo con lo que lo hace provoca que uno se pierda fácilmente. Deja tareas muy sencillas, y en todas las evaluaciones da posibilidades de puntos extra, por lo que lo recomiendo solo si usted es muy autodidacta.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra']::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '3d230fdc183e276aab97c346e9b5ea856e2e413937b722578648c67dd2c783ee'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'El profesor es muy cómodo para llevar un curso como CC porque aunque simplemente repasa una presentación prerealizada, los exámenes los realiza en base a esos ejercicios vistos en clase o en la presentación, provocando que sea fácil estudiar para los exámenes. Además de que brinda puntos extra.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Da crédito extra']::TEXT[], '2023-06-15T00:00:00+00:00'::TIMESTAMPTZ, '9e70a1d6d8daf2ddae83b4d173c819c67b315d17b0294d379cc72a850fb456ce'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Pésimo profesor, solo hay 4 cosas que tiene que calificar en todo el semestre y aún así lo hace mal. Se enoja si le preguntan cosas durante el experimento y tiene un egocentrismo que sobresale de su cuerpo. Lo único bueno que tiene es que ni revisa las bitácoras.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-07T00:00:00+00:00'::TIMESTAMPTZ, 'b4f6f3e398fa7426bfe51fdef2867c7b123a02d1dc077cb1057514ab02fa2ad8'::TEXT, ARRAY[1256]::BIGINT[]),
    (388::BIGINT, 'JP creo que detesta dar lecciones. A pesar de eso no ser problema de los estudiantes, si lo transmite en cada clase. Preparense para escuchar una voz monotona, desanimada y presentaciones aburridas. Internamente se clasifica como un profesor malo. Por lo menos en el curso de CC'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2023-02-11T00:00:00+00:00'::TIMESTAMPTZ, '36a324dfb05bd2a40cf65926d509a03263274ba8cf0e9967c0962782ff4f420b'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Es un buen profesor, explica muy bien, pero habla un poco lento entonces aburre, los ejercicios del examen son bastante parecidos a los que recomienda.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Da crédito extra']::TEXT[], '2023-01-17T00:00:00+00:00'::TIMESTAMPTZ, 'e92baf4eb0bede5630a773ed54e917880656046133028f729de82c006718f43a'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'El profesor no es la gran cosa, pero tampoco es malo para el curso de mediciones y CC. Habla lento, por lo que debes concentrarse bien. Aprendes lo justo para otros cursos (Ni menos, ni más).'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-28T00:00:00+00:00'::TIMESTAMPTZ, '925f32fa51677f5dd181a20c9a937f6e44bf3f2b18ed9ec582fc78a0892d7454'::TEXT, ARRAY[1256]::BIGINT[]),
    (388::BIGINT, 'El profesor da muchos ejemplos en clase, los exámenes son muy adecuados y da posibilidad para puntos extra. A veces se enreda explicando pero en lo general es muy preparado. Hay muchos examenes y las tareas son de selección única y valen mucho, haciendo que perder muchos puntos sea fácil.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Aspectos de calificación claros']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f079474b2d58d904082c551a617d06a1a54ade2b0216a6e91096ffe254d865c7'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Explica bastante bien, hace muchos ejemplos en la clase y resuelve dudas si se lo piden, el único problema es que habla muy lento y es fácil distraerse en su clase.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'e4c0f0c65735c4f33bfef3261f9350bc19e611116a3d6c172b60ea07896201a8'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Lo pasa cagado de risa si conoce a alguien que lo haya llevado virtual, mismos informes, mismos exámenes todo es igual. Las clases son muy aburridas y los labs presenciales se hacen en 15 minutos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2021-12-06T00:00:00+00:00'::TIMESTAMPTZ, '88d8bf6289c27485913b7c6a990a9ac1935a6f8bd8fa8ef147e690c45141ce1e'::TEXT, ARRAY[1256]::BIGINT[]),
    (388::BIGINT, 'El profe explica bastante bien y hace bastantes ejercicios, sin embargo, habla bastante lento y con una voz plana lo cual puede dificultar concentrarse pensaría que principalmente de manera virtual. Los exámenes no son difíciles, pero hay que estudiar y da puntos extra.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra']::TEXT[], '2021-11-27T00:00:00+00:00'::TIMESTAMPTZ, '362602147b5096bc63e19fda7ed44f60fb9f48daba696b0e1cd966bcb9450c1c'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Habla un poco lento y virtualmente puede ser pesado, sin embargo explica bien y reuelve ejercicios en clase. Los exámenes pueden ser regulares o difíciles, pero es suave para calificar, si lleva bien la materia y estudia lo necesario, se puede ya que el curso en sí es complicado.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Exámenes retadores']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, '453d78e7c28160c912d6d2afbbdb4d84018f7d74b58b1a8773f255efedb4fb43'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Clases súper aburridas y lentas, hace muchos ejercicios pero sencillos en comparación con los exámenes que son ejercicios difíciles'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2021-07-20T00:00:00+00:00'::TIMESTAMPTZ, '753423c966fe5f457b54294ab2ccc325548ae22227555609febfeb120ee632ce'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Profesor que solamente va a hablar a la clase, no motiva al estudiante a seguir, las clases siempre tienen la misma dinámica, los exámenes son muy diferentes a lo que se ve en clase, da puntos extras (es la salvación del curso), si mete tutorías tiene que hacer bastantes ejercicios entregables.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Da crédito extra', 'Exámenes retadores']::TEXT[], '2021-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'f9118ea94caa971696c823fc63cc458c64c99dea1516d57994758e0e02120e7d'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Para CC es muy buen profesor. Explica bien, resuelve bastantes ejercicios en clase, las tareas son bastante sencillas y da muchos puntos extra, eso si, habla bastante lento entonces debe tener algo de paciencia en clase; ver las clases en Youtube a 1,5 es buena idea. Tampoco es mala opcion para lab'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, '53d5239932585797c47d42b897bbc0536b1d5b887bd05694635a3a7a36a118fe'::TEXT, ARRAY[1257, 1256]::BIGINT[]),
    (388::BIGINT, 'Pésimo profe, no enseña nada, nunca corrige las cosas solo dice lo que está mal y ya. Es un bostezo y califica muy subjetivamente. Los instructivos siempre están mal redactados y es muy necio con las citas y para él todo es plagio. Las clases son demasiado aburridas. Califica todo demasiado tarde.'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2021-05-15T00:00:00+00:00'::TIMESTAMPTZ, '1cff1bc94229b72e291197240e440e58cede8dd28bcd7f85b8a3f2ec36211a5f'::TEXT, ARRAY[1256]::BIGINT[]),
    (388::BIGINT, 'La verdad es muy buen profesor. Se preocupa por el estudiante dejando bastantes opciones para puntos extra y haciendo muchos ejercicios en clase. Habla un poco lento, lo que ocasiona que sus clases sean largas, pero también es cierto que uno no se pierde. Yo la verdad sí lo recomiendo!'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-03-25T00:00:00+00:00'::TIMESTAMPTZ, '6047ff6eaf16a4020071809c10b142f5c74784c04d0a268258ad31933ac13d6f'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Este profesor es muy bueno y el curso es facil de pasar! Lleve CC con el y aprendi montones. Pase simplemente con sentarme a ver los videos en velocidad 1.5x y resolver los ejercicios que hace en clase. Hace mucha practica en clase, cosa que sirve montones. Excelente y super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'd72c339b1c03dd0e34ad8403ae97154d6273c81709fd9aaef6f3727ca2c9722e'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Apoya mucho al estudiante con bastantes puntos extra en tareas y ejercicios opcionales en exámenes Hay que ver los videos de las clases virtuales como a velocidad 1.5 para entenderle porque habla muy lento, pero explica muy bien, es el menos malo para CC. no metan con Sergio!'::TEXT, 4.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'La participación importa', 'Clases largas']::TEXT[], '2021-02-03T00:00:00+00:00'::TIMESTAMPTZ, 'ffaa03ca9a3eeadcc67d930b033ef63ec022e01538740f2bafab70e63ca8b5c8'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Considero que no es mal profesor, el enseña bien. No obstante uno no debe esperar a que con lo que el profe enseña pasaras, siempre será bueno que estudies y practiques la materia con ejemplos del libro.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-09-05T00:00:00+00:00'::TIMESTAMPTZ, '479f13540722ba7ecaeba00735a0af8eb897b6306ef5ba0f166d8b62561e57ad'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Explica muy bien, pero es aburrido. Los asistentes califican duro, pero uno le puede solicitar al profe que le recalifique una evaluación.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'd66546bc1ca144025b0c675bc73f3d560b799037cb4985e5c6a7d766e8f6e3c5'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Es inspiracional porque uno se da cuenta que si pierde el curso lo más probable es que nuevamente haya que llevarlo con él, porque los profesores buenos se van rápido. Estudie con el libro, y vaya a tutorías, de lo contrario si se queda con lo que Javi diga será imposible pasarlo.'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador']::TEXT[], '2018-10-15T00:00:00+00:00'::TIMESTAMPTZ, '5271e1037d9571955dc2ef1c43158d3f5242851ec60b56cabf81b6ef135e392f'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Las clases son DEMASIADO aburridas, el profesor da todo por entendido, por lo que prácticamente no le ayuda a los que apenas estamos aprendiendo, Sinceramente es muy mal profesor.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, 'f10e422f6db3623a791f099192f26001cc282ce983438f18405ce1fd4002d87a'::TEXT, ARRAY[1256]::BIGINT[]),
    (388::BIGINT, 'El profe da la clase completa y da toda la materia el curso. Es muy aburrido pero comparado con otros profes es bueno. A veces se confunde. Es de los mejores profes a la hora de revisar un examen.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2018-05-30T00:00:00+00:00'::TIMESTAMPTZ, '1c409e88a1888f52a667d55b16c230bd531f1b2a4d81e50be440f1cc2bbb2559'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Un bostezo, parece a Druppy'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-01T00:00:00+00:00'::TIMESTAMPTZ, 'ea9767dfda98629343c33d6a84f35e99ed45f0cd683e40c5a2a3e3ce5275fe68'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Es bastante perezoso y aburrido, las clases vienen directo del libro, no siempre es de ayuda en consulta pero de todas maneras no es tan mal Profesor y califica justo. Los laboratorios son un poco lentos, los trabajos previos, los quices y los reportes son un regalo, pero los informes son de cuidado'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '63d6897fbd51451d3aaa0d6b8b323c7e9276071d50de009e1b1561e0236ddaec'::TEXT, ARRAY[1257, 3050]::BIGINT[]),
    (388::BIGINT, 'Malo pero si está repitiendo tal vez sea una buena opción , pregunte como le gustan que sean resueltos los quices y examenes y use las convenciones que el usa , así es más fácil un reclamo por que general se enreda mucho'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'f87d7d056b302d862f251a14c883a493db8d48245d1f2610abcc69593d551776'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'La clase es un bostezo, y explicando no es muy bueno que digamos. Como ejemplos, usa ejercicios del libro que no siempre logra resolver y en general es malo'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, '8e91f02f0cf888b7e70c86cf249f152e6e4065580e697376a55fa6d0228cd64f'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Es decentemente bueno, pero he escuchado que hay mejores. Es estricto calificando informes y exámenes. A mi parecer aprendí y es un curso llevadero con él, por lo cual no es mala opción.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'bdcc4fcd16fa6b86d60b977c0ba2775e1581b2cd27915cc4eb3d83d7135341b1'::TEXT, ARRAY[927]::BIGINT[]),
    (388::BIGINT, 'Es un mal profesor, califica muy estricto pidiendo calidad, cuando él no la da.'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria']::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, '5b9a3e3a6d4f5c7b769ce72d215b8d78f7d6b7ab6e4027a1921d95503e7a6e28'::TEXT, ARRAY[927]::BIGINT[]),
    (388::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'a6557ef3ccde17de48ff0a223cbbc02bd4a305ae75b65992baff89f6413f777e'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Nunca sabe respondder a las preguntas de los estudiantes. Esta detras del palo. Pesimo profesor. No se aprende nada!!!!'::TEXT, 4.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-14T00:00:00+00:00'::TIMESTAMPTZ, 'f2d9d5fbc3f99348cc5a2f3e7b031c29d3a178cb850e0c5cf4f6f98633b5c84a'::TEXT, ARRAY[1257, 3060, 1277]::BIGINT[]),
    (388::BIGINT, 'El mae está mamando. Se nota que sabe mucho, pero no se sabe expresar en la clase. Se pasa equivocando a cada rato'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-12T00:00:00+00:00'::TIMESTAMPTZ, '6447dfaf84e3b61e1c6917a311b3594e9fc3a04bb167ae14eec5276bb9545730'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'Las calificaciones dependen del asistente, el profesor califica más suave. Intenta explicar pero algunas veces no le sale. En general, el curso se pasa con el libro.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, '7b71a5c3ce39faf25f1496a887d3fcd1191b8e0fc54fa6b2bbeb2052ac37a5ff'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'De los 3 profes es el que más explica. El curso es duro por si solo y se debe estudiar del libro, sin embargo si le pone atención puede llegar a estudiar del libro y entender con facilidad. No es el más facil, pero califica justamente una vez realiza las cosas como a él le gusta.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'fadc0dd458876221efce0188bdc30cb7d6652c767b8a1c9366ac68240c54908a'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'De los tres que dan el curso siento que es el mejor segun he escuchado, califica procedimiento, explica bien los temas y es ordenado con el cronograma'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-11-23T00:00:00+00:00'::TIMESTAMPTZ, '1b2383aa6cd17a7bd7ae5387d0b7c8988365c3ca5556d0e02232ca7ecd78ff01'::TEXT, ARRAY[1257]::BIGINT[]),
    (388::BIGINT, 'sus respuestas cuando un experimento no funciona son que la fuente no funciona, o es el color de los jumpers, en casos extremos te dice no sé. No ayuda como profesor, es una figura ficticia de ser humano, el cual por algún extraño motivo sigue dando cursos. Carece de toda pedagogía y habicomunicatva'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, '55bf298b436191871f9712ab90105a98607ff70e6b6e8c672a5e1513f6b65fb3'::TEXT, ARRAY[1277]::BIGINT[]),
    (388::BIGINT, 'Pésimo profesor. No explica, a veces ni sabe qué hacer. Califica injustamente y dura mucho en devolver evaluaciones.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'af7d0901aeb5a0fa22b236ad60dfdec987ca1052d3dad999dcca7fada97fb3fa'::TEXT, ARRAY[1277]::BIGINT[]),
    (388::BIGINT, 'No sabe explicar pero si quiere pasar fácil sin aprender nada es él indicado'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-23T00:00:00+00:00'::TIMESTAMPTZ, '75b0c9b74e6b619c7aae7d7b59dbfdcb2744d22c336dfbf2f4081d882708e718'::TEXT, ARRAY[927]::BIGINT[]),
    (388::BIGINT, 'Es buen profe, su rubrica en laboratorio te da mucho chance de pasar.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, '59e6c3889bb3ee2984136794a9aa66dc9002e8f55acbb7113008fd1b8f62043a'::TEXT, ARRAY[1352]::BIGINT[]),
    (388::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-15T00:00:00+00:00'::TIMESTAMPTZ, 'b0799da6d413ec929025069965aa39bb7644ac376d71a4a0c2ec25bd3f236d03'::TEXT, ARRAY[1262]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
